def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])
    background = grid[0][0]

    output = [[background for _ in range(cols)] for _ in range(rows)]

    # Collect non-background pixels in reading order
    sources = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background:
                sources.append((r, c, grid[r][c]))

    # For each source, draw up-left anti-diagonal
    for r0, c0, val in sources:
        r, c = r0, c0
        while r >= 0 and c >= 0:
            output[r][c] = val
            r -= 1
            c -= 1

    return output
